  function handleLogin(event) {
    event.preventDefault();
    const form = event.target;
    const email = form.querySelector("#email").value;
    const password = form.querySelector("#password").value;
    cms.login(email, password).then(() => {
      showLoginModal.value = false;
      showNotification("Welcome back, " + cms.currentUser.displayName + "!");
    }).catch(error => {
      showNotification("Login failed: " + error.message, "error");
    });
  }

  function handleLogout() {
    cms.logout().then(() => {
      showLoginModal.value = true;
      showNotification("You have been logged out");
    });
  }

  function navigateTo(view) {
    cms.setView(view);
    unknown;
  }

  function handleNewPost() {
    cms.currentPost = null;
    cms.setEditorContent("");
    cms.setView("editor");
  }

  function handleEditPost(post) {
    cms.loadPost(post.id).then(() => {
      cms.setView("editor");
    });
  }

  function handleDeletePost(post) {
    deleteTargetId.value = post.id;
    showDeleteConfirm.value = true;
  }

  function confirmDelete() {
    cms.deletePost(deleteTargetId.value).then(() => {
      showNotification("Post deleted successfully");
      showDeleteConfirm.value = false;
    }).catch(error => {
      showNotification("Delete failed: " + error.message, "error");
    });
  }

  function handlePublishPost(post) {
    cms.publishPost(post.id).then(() => {
      showNotification("Post published successfully!");
    }).catch(error => {
      showNotification("Publish failed: " + error.message, "error");
    });
  }

  function handleMediaUpload(event) {
    const files = event.target.files;
    if (!files || files.length === 0)   return;
    const file = files[0];
    cms.uploadMediaFile(file).then(mediaFile => {
      showNotification("File uploaded: " + mediaFile.filename);
    }).catch(error => {
      showNotification("Upload failed: " + error.message, "error");
    });
  }

  function handleMediaDelete(media) {
    if (confirm("Delete " + media.filename + "?")) {
      cms.deleteMediaFile(media.id).then(() => {
        showNotification("Media file deleted");
      }).catch(error => {
        showNotification("Delete failed: " + error.message, "error");
      });
    }
  }

  function showNotification(message, type = "success") {
    notification.value = message;
    notificationVisible.value = true;
    setTimeout(() => {
      notificationVisible.value = false;
    }, 3000);
  }

